	divided_monarchists_ai_bonapartist = yes
	divided_monarchists_ai_house_hooks_active = yes
}

divided_monarchists_ai_backs_monarchist = {
	divided_monarchists_ai_monarchist = yes
	divided_monarchists_ai_house_hooks_active = yes
}

divided_monarchists_ai_path_is_ruler = {
	OR = {
		AND = {
			divided_monarchists_ai_orleanist = yes
			ruler_is_orleanist = yes
		}
		AND = {
			divided_monarchists_ai_legitimist = yes
			ruler_is_legitimist = yes
		}
		AND = {
			divided_monarchists_ai_bonapartist = yes
			ruler_is_bonapartist = yes
		}
	}
}

ai_avoids_radicals = {
	OR = {
		AND = {
			has_journal_entry = je_divided_monarchists
			divided_monarchists_ai_monarchist = yes
		}
	}
}

ai_wants_radicals = {
	OR = {
		AND = {
			has_journal_entry = je_divided_monarchists
			divided_monarchists_ai_republican = yes
		}
	}
}

character_is_french_house = {
	OR = {
		has_ideology = ideology:ideology_orleanist
		has_ideology = ideology:ideology_legitimist
		has_ideology = ideology:ideology_bonapartist
	}
}

character_matches_divided_monarchists_ai_path = {
	OR = {
		AND = {
			owner ?= { divided_monarchists_ai_backs_orleanist = yes }
			has_ideology = ideology:ideology_orleanist
		}
		AND = {
			owner ?= { divided_monarchists_ai_backs_legitimist = yes }
			has_ideology = ideology:ideology_legitimist
		}
		AND = {
			owner ?= { divided_monarchists_ai_backs_bonapartist = yes }
			has_ideology = ideology:ideology_bonapartist
		}
		AND = {
			owner ?= { divided_monarchists_ai_republican = yes }
			OR = {
				has_ideology = ideology:ideology_republican_leader
				has_ideology = ideology:ideology_radical
				has_ideology = ideology:ideology_positivist
			}
		}
	}
}

character_is_rival_french_house = {
	owner ?= { divided_monarchists_ai_backs_monarchist = yes }
	character_is_french_house = yes
	NOT = { character_matches_divided_monarchists_ai_path = yes }
}

divided_monarchists_ai_rejects_law = {
	ai_wants_radicals = yes
	OR = {
		scope:law.type ?= law_type:law_secret_police
		scope:law.type ?= law_type:law_outlawed_dissent
	}
}

ai_ceding_state_would_isolate_states = {
	$STATE$ = { has_port_state = yes }
	$RECEIVER$ = {
		NOT = { market = $CEDER$.market }
	}
	NOT = {
		$CEDER$.market = {
			any_scope_country = {
				any_scope_state = {
					NOT = { this = $STATE$ }
					has_port_state = yes
					is_in_same_market_area = $STATE$
				}
			}
		}
	}
	OR = {
		AND = {
			$STATE$ = {
				NOT = { is_in_same_market_area = $CEDER$.capital }
				any_neighbouring_state = {
					is_in_same_market_area = $STATE$
				}
			}
		}
		AND = {
			$STATE$ = { is_in_same_market_area = $CEDER$.capital }
			$CEDER$ = {
				any_scope_state = {
					NOT = { is_in_same_market_area = $CEDER$.capital }
				}
			}
		}
	}
}
